public boolean buscar(int[] arr, int a, int b, int x) {
    while (a <= b && x >= arr[a] && x <= arr[b]) {
        long num = ((long) b - a) * ((long) x - arr[a]);
        long den = (long) arr[b] - arr[a];
        if (den == 0)
            return arr[a] == x;
        int p = a + (int) (num / den);
        if (arr[p] == x)
            return true;
        else if (x > arr[p])
            a = p + 1;
        else
            b = p - 1;
    }
    return false;
}

capitulo-7/4-busqueda-saltos.md.code:
public boolean buscar(int[] arr, int x) {
    int n = arr.length, anterior = 0;
    if (n == 0)
        return false;
    int paso = (int) Math.floor(Math.sqrt(n)), delta = paso;
    // Avanzar en saltos hasta encontrar el rango
    while (arr[Math.min(delta, n) - 1] < x) {
        anterior = delta;
        delta = (int) Math.min((long) delta + paso, n);
        if (anterior >= n)
            return false; // Elemento fuera del rango de búsqueda
    }
    // Realiza la búsqueda lineal en el rango identificado
    for (int i = anterior; i < Math.min(delta, n); i++) {
        if (arr[i] == x)
            return true; // Elemento encontrado
    }
    return false; // Elemento no encontrado
}

capitulo-7/5-busqueda-exponencial.md.code:
public boolean buscar(int[] arr, int x) {
    int n = arr.length;
    if (n == 0)
        return false;
    // Verificar si el primer elemento es el buscado
    if (arr[0] == x)
        return true;
    // Encuentra el rango utilizando crecimiento exponencial
    int i = 1;
    while (i < n && arr[i] <= x)
        i = (int) Math.min((long) i * 2, n);
    // Determina los limites y ejecuta la búsqueda binaria
    int a = i/2;
    int b = Math.min(i, n - 1);
    // Invoca la función que aplica la búsqueda
    return busquedaBinaria(arr, a, b, x);
}

public boolean busquedaBinaria(int[] arr, int a, int b, int x) {
    while (a <= b) {
        // Posición en la mitad del rango [a,b]
        int m = a + (b - a) / 2;
        if (arr[m] == x)
            return true; // Elemento encontrado
        else if (x > arr[m])
            a = m + 1; // Buscar en la mitad derecha
        else
            b = m - 1; // Buscar en la mitad izquierda
    }
    return false; // Elemento no encontrado
}

