public void ordenar(int[] arr, int a, int b) {
    if (a >= b)
        return;
    int p = particionar(arr, a, b);
    ordenar(arr, a, p - 1);
    ordenar(arr, p + 1, b);
}
public int particionar(int[] arr, int a, int b) {
    int pivote = arr[a], i = a + 1, j = b;
    while (i <= j) {
        while (i <= j && arr[i] < pivote)
            i++;
        while (i <= j && arr[j] > pivote)
            j--;
        if (i <= j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }
    int temp = arr[a];
    arr[a] = arr[j];
    arr[j] = temp;
    return j;
}

